SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; SET NOCOUNT ON;
SELECT 'H' k, BbyNumber, ISNULL(OfferId,'') OfferId, REPLACE(ISNULL(Description,''),'|','/') d, ISNULL(LinkCategoryBuy,'') lb, ISNULL(LinkCategoryGet,'') lg, MinValue, MaxValue, LimitNumber, ISNULL(CondTargetType,'') tt, ISNULL(OriginFilter,'') o, ISNULL(Includes,'') inc, ISNULL(Excludes,'') exc FROM BbyHeader WHERE ValidFrom <= '20261128' AND ValidTo >= '20261128' AND ISNULL(BbyStatus,'') NOT IN ('2');
SELECT 'P' k, p.BbyNumber, p.PrereqNumber, p.MatItemPos, ISNULL(p.MaterialNumber,'') m, p.Qty, ISNULL(p.Uom,'') u, ISNULL(p.NumberAsTotal,'') t, p.MinValue FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY BbyNumber, PrereqNumber ORDER BY MatItemPos) rn FROM BbyPrereq) p JOIN BbyHeader h ON h.BbyNumber=p.BbyNumber AND h.ValidFrom <= '20261128' AND h.ValidTo >= '20261128' WHERE p.rn <= 8;
SELECT 'C' k, c.BbyNumber, c.CondNumber, ISNULL(c.DiscountType,'') dt, c.CondValue, c.CondValueP, c.Qty, ISNULL(c.Uom,'') u, ISNULL(c.ScaleType,'') s, ISNULL(c.CondReference,'') r, ISNULL(c.NumberAsTotal,'') t FROM BbyCond c JOIN BbyHeader h ON h.BbyNumber=c.BbyNumber AND h.ValidFrom <= '20261128' AND h.ValidTo >= '20261128';
SELECT 'M' k, m.BbyNumber, m.CondNumber, m.MaterialNumber, ISNULL(m.Uom,'') u, m.cnt FROM (SELECT x.*, ROW_NUMBER() OVER (PARTITION BY x.BbyNumber, x.CondNumber ORDER BY x.MaterialNumber) rn, COUNT(*) OVER (PARTITION BY x.BbyNumber, x.CondNumber) cnt FROM BbyCond201 x) m JOIN BbyHeader h ON h.BbyNumber=m.BbyNumber AND h.ValidFrom <= '20261128' AND h.ValidTo >= '20261128' WHERE m.rn <= 8;
